/// <reference lib="webworker" />
// kernel.wasm: generated by tools/build-kernel.sh (packages/kernel-wasm/dist).
import wasmUrl from "../dist/kernel.wasm?url";
import gcsWasmUrl from "@salusoft89/planegcs/dist/planegcs_dist/planegcs.wasm?url";
import type { KernelRequestExt, KernelResponse, RecomputeResult } from "@solidus-cad/sdk";
import { SketchSolver } from "@solidus-cad/sketch";
import { WasmKernelEngine } from "./engine.ts";

declare const self: DedicatedWorkerGlobalScope;

const solver = SketchSolver.create(gcsWasmUrl);
let engine = solver.then((s) => WasmKernelEngine.create(s, wasmUrl));

/**
 * Stop of the WASM module (abort: internal error, memory exhausted): the instance is unusable, all following requests
 * would fail. A new instance is loaded; the requests carry the full document, so nothing is lost.
 */
function aborted(e: unknown): boolean {
  return e instanceof WebAssembly.RuntimeError || /Aborted/.test(String(e));
}

engine.then(
  () => self.postMessage({ id: 0, ok: true, result: "ready" } satisfies KernelResponse),
  (e) => self.postMessage({ id: 0, ok: false, error: `Chargement du noyau impossible : ${e}` } satisfies KernelResponse),
);

self.onmessage = async (ev: MessageEvent<KernelRequestExt>) => {
  const req = ev.data;
  try {
    const k = await engine;
    if (req.kind === "recompute") {
      const result: RecomputeResult = k.recompute(req.doc, req.opts);
      const m = result.mesh;
      const transfer = m
        ? [m.positions, m.normals, m.indices, m.faceGroups, m.edges, m.edgeGroups].map((a) => a.buffer)
        : [];
      self.postMessage({ id: req.id, ok: true, result } satisfies KernelResponse, transfer);
    } else if (req.kind === "projectScene" || req.kind === "project") {
      const views = req.kind === "project" ? k.project(req.doc, req.views) : k.projectScene(req.items, req.views);
      const transfer = views.flatMap((v) => [v.visible.buffer, v.hidden.buffer, v.circles.buffer, ...(v.hatches ?? []).map((h) => h.segments.buffer)]);
      self.postMessage({ id: req.id, ok: true, result: views } satisfies KernelResponse, transfer);
    } else if (req.kind === "camMesh") {
      const m = k.camMesh(req.doc, req.deflection);
      const transfer = m ? [m.positions, m.normals, m.indices, m.faceGroups, m.edges, m.edgeGroups].map((a) => a.buffer) : [];
      self.postMessage({ id: req.id, ok: true, result: m } satisfies KernelResponse, transfer);
    } else if (req.kind === "surfaceAnalysis") {
      const values = k.surfaceAnalysis(req.doc, req.analysis);
      self.postMessage({ id: req.id, ok: true, result: values } satisfies KernelResponse, [values.buffer]);
    } else if (req.kind === "continuity") {
      self.postMessage({ id: req.id, ok: true, result: k.continuity(req.doc, req.edge) } satisfies KernelResponse);
    } else if (req.kind === "flatPattern") {
      const f = k.flatPattern(req.doc);
      self.postMessage({ id: req.id, ok: true, result: f } satisfies KernelResponse, [f.outline.buffer, f.circles.buffer]);
    } else if (req.kind === "interferences") {
      self.postMessage({ id: req.id, ok: true, result: k.interferences(req.parts) } satisfies KernelResponse);
    } else if (req.kind === "exportPlaced") {
      const data = k.exportPlaced(req.format, req.parts);
      self.postMessage({ id: req.id, ok: true, result: data } satisfies KernelResponse, [data.buffer]);
    } else if (req.kind === "featureAt") {
      self.postMessage({ id: req.id, ok: true, result: k.featureAt(req.docId, req.faceId) } satisfies KernelResponse);
    } else if (req.kind === "forget") {
      k.forget(req.docId);
      self.postMessage({ id: req.id, ok: true, result: null } satisfies KernelResponse);
    } else if (req.kind === "export") {
      const data = k.exportShape(req.format, req.docId);
      self.postMessage({ id: req.id, ok: true, result: data } satisfies KernelResponse, [data.buffer]);
    } else {
      throw new Error(`Requête inconnue : ${(req as { kind: string }).kind}`);
    }
  } catch (e) {
    let error = e instanceof Error ? e.message : String(e);
    if (aborted(e)) {
      engine = solver.then((s) => WasmKernelEngine.create(s, wasmUrl));
      error = `Le noyau s'est arrêté sur une erreur interne (${error}) ; il a été relancé.`;
    }
    self.postMessage({ id: req.id, ok: false, error } satisfies KernelResponse);
  } finally {
    // Between two requests: frees the least recent documents (bounded WASM memory).
    (await engine.catch(() => null))?.trim();
  }
};
